import json
from glue import Infra3

# Initialize the infrastructure
g = Infra3("cmdb.json", "monitoring.json", "mapping_tables.json")

# Find the component by display name
target_component = None
for ci in g.components():
    if ci not in g.stale:
        names = g.names_of(ci)
        # Check if "Metrics Ingest Service" is in the display names or aliases
        for name in names:
            if name == "Metrics Ingest Service":
                target_component = ci
                break
    if target_component:
        break

# If not found by display name, search in monitoring data
if not target_component:
    with open("monitoring.json") as f:
        monitoring_data = json.load(f)
    for record in monitoring_data.get("records", []):
        if record.get("display_name") == "Metrics Ingest Service":
            # Try to resolve this component
            try:
                target_component = g.resolve(record.get("component"))
            except KeyError:
                # Component might not be in CMDB, try by component name
                for ci in g.components():
                    if ci not in g.stale:
                        names = g.names_of(ci)
                        if record.get("component") in names:
                            target_component = ci
                            break
            break

# If still not found, try resolving by the display name or component directly
if not target_component:
    try:
        # Try common naming patterns
        target_component = g.resolve("metrics_ingest_svc")
    except KeyError:
        try:
            target_component = g.resolve("mon:metrics-ingest")
        except KeyError:
            pass

# Check if the service is down when dc-iad fails
if target_component and target_component not in g.stale:
    is_down = g.is_down(target_component, "dc-iad")
    result = is_down
else:
    # Component not found or is stale
    result = False

print(json.dumps({"answer_type": "bool", "answer": result}))
